INSERT INTO public.companies (slug, name, subsector_id, website, chains, tags, meta)
SELECT v.slug, v.name, s.id, v.website, v.chains, v.tags, v.meta
FROM (VALUES
  ('core-protocol-development-led-by-starkware-with-governance-progressively-transitioning-toward-the-starknet-ecosystem', 'Core protocol development led by StarkWare, with governance progressively transitioning toward the Starknet ecosystem.', 'rollup-scaling-frameworks', 'zk-rollups', 'https://starknet.io', ARRAY['Not natively positioned as an appchain factory', 'focus is on a shared execution environment.']::text[], ARRAY[]::text[], '{"description": "An Ethereum L2 validity (ZK) rollup that executes transactions off L1 and settles state to Ethereum using STARK-based validity proofs, optimized for scalability and cryptographic soundness.", "extras": {"Cost Sensitivity to Usage": "Economically improves with scale (batching efficiency); marginal costs still sensitive to L1 calldata pricing and prover load.", "Decentralization Roadmap Credibility": "Clear, multi-year roadmap emphasizing sequencer decentralization, prover decentralization, and governance handoff; execution remains ongoing rather than complete.", "Dependency on External Bridges": "Relies on external bridges and messaging layers for cross-chain interoperability beyond Ethereum.", "Developer Adoption Signal": "Strong adoption among teams willing to build in Cairo; distinct developer ecosystem compared to EVM-centric rollups.", "Ecosystem Dependency Risk": "High dependency on Cairo tooling, StarkWare-led protocol evolution, and STARK-specific infrastructure.", "Emergency Controls": "Emergency intervention and pause mechanisms exist at the protocol level.", "Enterprise / Institutional Orientation": "Appeals to teams prioritizing cryptographic robustness and long-term scalability; steeper learning curve for traditional Solidity teams.", "Ethereum Composability Model": "Asynchronous composability via Ethereum settlement and messaging.", "Ethereum Settlement Path": "L2 execution → batch commitment → STARK proof generation → L1 verification contract → finalized L2 state on Ethereum.", "Execution Environment": "Custom VM (Cairo VM); not EVM-equivalent.", "Is This a Network or a Framework": "Primarily a network, with reusable components (e.g., StarkEx) but not positioned as a general-purpose rollup SDK in the same way as OP Stack or ZK Stack.", "Mainnet Maturity": "Live mainnet with continuous upgrades; maturity measured by stability improvements rather than static design.", "Native Cross-Rollup Support": "No native cross-rollup interoperability at the protocol level.", "Opinionated vs Modular Design": "Highly opinionated, favoring Cairo, STARK proofs, and non-EVM execution.", "Permissioned vs Permissionless Deployment": "Operation is currently more permissioned, with permissionlessness and decentralization targeted via roadmap.", "Practitioner’s Note": "If Starknet were removed, Ethereum would lose its primary STARK-based ZK rollup, eliminating a major alternative proof system and execution paradigm.", "Proof System Type": "STARK-based (transparent, no trusted setup).", "Prover Architecture": "Currently permissioned / operator-led proving, with decentralization of proving infrastructure as a stated roadmap goal.", "Prover Bottlenecks": "- Compute-intensive proving\n- Specialized hardware and optimization requirements\n- Centralization risk until prover decentralization is achieved", "Proving Cost Characteristics": "High fixed prover costs with favorable scaling at high throughput due to STARK aggregation efficiency.", "Reason for Inclusion": "Implements production ZK-rollup infrastructure where state correctness is enforced via STARK validity proofs verified on Ethereum, representing a distinct design path from SNARK-based ZK rollups.", "Reorg / Failure Handling Model": "- Post-L1 verification: no L2 reorg risk beyond Ethereum finality\n- Pre-finalization: soft finality depends on sequencer behavior and operational stability", "Reusable by Other Rollups": "Partially, StarkWare’s technology stack (e.g., StarkEx) has powered multiple systems, but Starknet itself is a canonical network.", "Security Inheritance from Ethereum": "Full settlement security once proofs are verified and state roots are finalized on Ethereum.", "Sequencer Model": "Single sequencer today; sequencer decentralization planned but not fully implemented.", "Shared Prover / Sequencer Assumptions": "Currently centralized at the network level; shared assumptions apply across Starknet until decentralization milestones are reached.", "Single Canonical Rollup": "Yes, Starknet is positioned as a single canonical ZK rollup.", "State Transition Definition": "Defined by Starknet protocol specifications and Cairo execution semantics; changes require protocol upgrades coordinated by governance.", "Throughput Constraints": "Bounded by prover throughput, Cairo VM execution limits, and Ethereum data posting constraints.", "Time to Cryptographic Finality": "Finality achieved when STARK proofs are verified and state updates are finalized on Ethereum (typically minutes to hours depending on batching/proving cadence).", "Trust Assumptions Beyond Ethereum": "- Correctness and soundness of STARK prover implementation\n- Liveness and honesty of sequencer/prover prior to L1 finalization\n- No trusted setup assumption (key STARK advantage)", "Upgrade Authority": "Protocol upgrades controlled via governance mechanisms and admin contracts; practitioners should assume active upgrade authority exists.", "Validity Proof Model": "Aggregated STARK proofs generated over batches of transactions; recursion used to improve scalability and verification efficiency.", "Verifier Location": "Ethereum L1 smart contracts verify STARK proofs and finalize state updates.", "Withdrawal Latency": "Withdrawals are gated by L1 proof verification and finalization; generally faster than optimistic rollups but dependent on proving cadence.", "ZK Rollup": "Starknet"}, "source_label": "ZK Rollups"}'::jsonb),
  ('developed-and-maintained-by-the-scroll-core-team-governance-and-decentralization-mechanisms-continue-to-evolve', 'Developed and maintained by the Scroll core team; governance and decentralization mechanisms continue to evolve.', 'rollup-scaling-frameworks', 'zk-rollups', 'https://scroll.io', ARRAY['Not a primary design goal.']::text[], ARRAY[]::text[], '{"description": "An Ethereum L2 ZK validity rollup focused on EVM equivalence, executing transactions off L1 and settling state to Ethereum via validity proofs verified on L1.", "extras": {"Cost Sensitivity to Usage": "Costs improve with higher utilization and batching efficiency; sensitive to Ethereum L1 gas prices.", "Decentralization Roadmap Credibility": "Clear roadmap emphasis on sequencer and prover decentralization; current state remains operator-led.", "Dependency on External Bridges": "Relies on external bridges and messaging layers for cross-chain interoperability.", "Developer Adoption Signal": "Strong adoption among teams prioritizing full EVM equivalence and minimal migration risk from Ethereum L1.", "Ecosystem Dependency Risk": "Dependency on Scroll-specific prover infrastructure and the pace of decentralization milestones.", "Emergency Controls": "Emergency pause and intervention mechanisms are present at the protocol level.", "Enterprise / Institutional Orientation": "Well-suited for teams requiring Ethereum-like execution semantics and predictable behavior.", "Ethereum Composability Model": "Asynchronous composability via Ethereum settlement and messaging.", "Ethereum Settlement Path": "L2 execution → batch commitment → SNARK proof generation → L1 verification contract → finalized state on Ethereum.", "Execution Environment": "EVM-equivalent (bytecode-level equivalence with Ethereum).", "Is This a Network or a Framework": "Primarily a network; not positioned as a generalized rollup SDK like OP Stack or ZK Stack.", "Mainnet Maturity": "Live mainnet with incremental hardening; maturity measured via correctness and stability rather than rapid feature expansion.", "Native Cross-Rollup Support": "No native cross-rollup interoperability at the protocol level.", "Opinionated vs Modular Design": "Highly opinionated, prioritizing EVM equivalence and correctness over modular flexibility.", "Permissioned vs Permissionless Deployment": "Currently more permissioned, with permissionlessness targeted via decentralization roadmap.", "Practitioner’s Note": "If Scroll were removed, Ethereum would lose a ZK rollup explicitly designed to mirror L1 EVM semantics exactly at the protocol level.", "Proof System Type": "SNARK-based (zk-SNARK family).", "Prover Architecture": "Currently permissioned / operator-led proving; decentralization of proving infrastructure is a roadmap objective.", "Prover Bottlenecks": "- Compute-intensive proving\n- Specialized hardware requirements\n- Centralization risk until prover decentralization", "Proving Cost Characteristics": "Meaningful fixed prover costs with marginal costs improving as batches scale.", "Reason for Inclusion": "Implements a production ZK rollup whose defining characteristic is bytecode-level EVM equivalence, minimizing semantic differences between Ethereum L1 and L2.", "Reorg / Failure Handling Model": "- Post-L1 finalization: no L2 reorg risk beyond Ethereum\n- Pre-finalization: soft finality depends on sequencer/prover behavior", "Reusable by Other Rollups": "Limited, core technology could be reused, but Scroll is not marketed as a rollup-as-a-service framework.", "Security Inheritance from Ethereum": "Full settlement security once proofs are verified and finalized on Ethereum.", "Sequencer Model": "Single sequencer today with plans for progressive decentralization.", "Shared Prover / Sequencer Assumptions": "Currently shared at the network level.", "Single Canonical Rollup": "Yes, Scroll is positioned as a single canonical ZK rollup.", "State Transition Definition": "Defined by Ethereum’s EVM specification; Scroll mirrors L1 behavior with minimal deviations. Protocol upgrades track Ethereum changes closely.", "Throughput Constraints": "Bounded by prover throughput, Ethereum calldata constraints, and batch sizing.", "Time to Cryptographic Finality": "Achieved when the validity proof is verified and the state update is finalized on Ethereum (typically minutes to hours depending on batching/proving cadence).", "Trust Assumptions Beyond Ethereum": "- Correctness of circuits and prover implementation\n- Trusted setup assumptions (typical for SNARK systems)\n- Sequencer/prover liveness assumptions before L1 finalization", "Upgrade Authority": "Admin / governance-controlled upgrades; practitioners should assume active upgrade authority exists.", "Validity Proof Model": "Batch validity proofs; aggregation and recursion used to amortize verification costs over many transactions.", "Verifier Location": "Ethereum L1 smart contracts verify proofs and finalize state roots.", "Withdrawal Latency": "Withdrawals are available after L1 proof verification and finalization; generally faster than optimistic rollups and dependent on proving cadence.", "ZK Rollup": "Scroll"}, "source_label": "ZK Rollups"}'::jsonb),
  ('developed-and-maintained-by-polygon-labs-governance-mechanisms-are-evolving-alongside-polygon-s-broader-ecosystem-governance', 'Developed and maintained by Polygon Labs; governance mechanisms are evolving alongside Polygon’s broader ecosystem governance.', 'rollup-scaling-frameworks', 'zk-rollups', 'https://polygon.technology/polygon-zkevm', ARRAY['Not a primary design goal.']::text[], ARRAY[]::text[], '{"description": "An Ethereum L2 ZK validity rollup that executes transactions off L1 and settles state to Ethereum using SNARK-based validity proofs, with a strong emphasis on EVM equivalence.", "extras": {"Cost Sensitivity to Usage": "Costs scale favorably with batching efficiency but remain sensitive to Ethereum L1 gas prices.", "Decentralization Roadmap Credibility": "Clear roadmap toward sequencer and prover decentralization, though current operation remains relatively centralized.", "Dependency on External Bridges": "Relies on external bridges and messaging layers for cross-chain interoperability.", "Developer Adoption Signal": "Strong interest from teams already integrated into the Polygon ecosystem and from Ethereum-native teams seeking zkEVM compatibility.", "Ecosystem Dependency Risk": "Dependency on Polygon Labs for protocol evolution and on shared Polygon ecosystem infrastructure.", "Emergency Controls": "Emergency pause and intervention mechanisms are present at the protocol level.", "Enterprise / Institutional Orientation": "High, Polygon zkEVM benefits from Polygon’s enterprise relationships and brand recognition.", "Ethereum Composability Model": "Asynchronous composability via Ethereum settlement and messaging.", "Ethereum Settlement Path": "L2 execution → batch commitment → SNARK proof generation → L1 verification contract → finalized L2 state on Ethereum.", "Execution Environment": "EVM-equivalent (bytecode-level compatibility with Ethereum).", "Is This a Network or a Framework": "Primarily a network, not positioned as a generalized rollup SDK.", "Mainnet Maturity": "Live mainnet with ongoing optimization; maturity reflected in correctness and EVM compatibility rather than maximal throughput.", "Native Cross-Rollup Support": "No native cross-rollup interoperability at the protocol level.", "Opinionated vs Modular Design": "Highly opinionated, optimizing for EVM equivalence and alignment with Ethereum semantics.", "Permissioned vs Permissionless Deployment": "Currently more permissioned, with permissionlessness planned via decentralization milestones.", "Practitioner’s Note": "If Polygon zkEVM were removed, Ethereum would lose a ZK rollup explicitly designed for strict EVM equivalence backed by validity proofs, distinct from Polygon PoS and other sidechains.", "Proof System Type": "SNARK-based (zk-SNARK family).", "Prover Architecture": "Currently permissioned / operator-led proving; prover decentralization is part of the long-term roadmap.", "Prover Bottlenecks": "- Compute-heavy proving workloads\n- Specialized hardware requirements\n- Centralization risk until prover participation broadens", "Proving Cost Characteristics": "High fixed prover costs with improved marginal efficiency as transaction volume increases.", "Reason for Inclusion": "Implements production ZK-rollup infrastructure where Ethereum-equivalent execution semantics are enforced through validity proofs verified on Ethereum.", "Reorg / Failure Handling Model": "- Post-L1 finalization: no L2 reorg risk beyond Ethereum\n- Pre-finalization: soft finality subject to sequencer/prover availability", "Reusable by Other Rollups": "Limited, core zkEVM technology could be reused, but Polygon zkEVM is not marketed as a rollup-as-a-service framework.", "Security Inheritance from Ethereum": "Full settlement security once proofs are verified and finalized on Ethereum.", "Sequencer Model": "Single sequencer in current operation, with decentralization planned.", "Shared Prover / Sequencer Assumptions": "Currently centralized at the network level.", "Single Canonical Rollup": "Yes, Polygon zkEVM operates as a single canonical ZK rollup.", "State Transition Definition": "Defined by Ethereum’s EVM specification; Polygon zkEVM tracks L1 semantics closely, with protocol upgrades aligned to Ethereum hard forks.", "Throughput Constraints": "Limited by prover throughput, Ethereum calldata costs, and batch aggregation efficiency.", "Time to Cryptographic Finality": "Final when the validity proof is verified and the state update is finalized on Ethereum (typically minutes to hours depending on batch size and proving cadence).", "Trust Assumptions Beyond Ethereum": "- Correctness of zkEVM circuits and prover implementation\n- Trusted setup assumptions inherent to SNARK systems\n- Sequencer/prover liveness prior to L1 finalization", "Upgrade Authority": "Protocol upgrades controlled by governance/admin mechanisms; practitioners should assume active upgrade authority exists.", "Validity Proof Model": "Aggregated batch validity proofs; recursion used to reduce on-chain verification overhead.", "Verifier Location": "Ethereum L1 smart contracts verify proofs and finalize state roots.", "Withdrawal Latency": "Withdrawals available after L1 proof verification and finalization; significantly faster than optimistic rollups and dependent on proving cadence.", "ZK Rollup": "Polygon zkEVM"}, "source_label": "ZK Rollups"}'::jsonb),
  ('developed-and-maintained-by-consensys-with-governance-processes-evolving-alongside-protocol-maturity', 'Developed and maintained by ConsenSys, with governance processes evolving alongside protocol maturity.', 'rollup-scaling-frameworks', 'zk-rollups', 'https://linea.build', ARRAY['Not a primary design goal.']::text[], ARRAY[]::text[], '{"description": "An Ethereum L2 ZK validity rollup developed by Consensys that executes transactions off L1 and settles state to Ethereum using SNARK-based validity proofs, with a strong focus on EVM equivalence and Ethereum-native tooling.", "extras": {"Cost Sensitivity to Usage": "Costs scale favorably with batching efficiency but remain sensitive to Ethereum L1 gas prices.", "Decentralization Roadmap Credibility": "Roadmap includes sequencer and prover decentralization; current operation remains more centralized, consistent with early-to-mid lifecycle ZK rollups.", "Dependency on External Bridges": "Relies on external bridges and messaging layers for cross-chain interoperability.", "Developer Adoption Signal": "Strong adoption driven by native integration with MetaMask, Infura, and ConsenSys tooling, reducing onboarding friction for Ethereum developers.", "Ecosystem Dependency Risk": "Significant dependency on ConsenSys for protocol evolution, infrastructure operation, and roadmap execution.", "Emergency Controls": "Emergency pause and intervention mechanisms are present at the protocol level.", "Enterprise / Institutional Orientation": "High, Linea benefits from ConsenSys’ enterprise relationships and regulatory engagement.", "Ethereum Composability Model": "Asynchronous composability via Ethereum settlement and messaging.", "Ethereum Settlement Path": "L2 execution → batch commitment → SNARK proof generation → L1 verifier contracts → finalized L2 state on Ethereum.", "Execution Environment": "EVM-equivalent, designed to closely mirror Ethereum L1 execution semantics.", "Is This a Network or a Framework": "Primarily a network, not marketed as a general-purpose rollup SDK.", "Mainnet Maturity": "Live mainnet with conservative iteration; maturity measured by stability and compatibility rather than aggressive throughput claims.", "Native Cross-Rollup Support": "No native cross-rollup interoperability at the protocol level.", "Opinionated vs Modular Design": "Relatively opinionated, prioritizing Ethereum equivalence, stability, and tooling integration over modular experimentation.", "Permissioned vs Permissionless Deployment": "Currently more permissioned, with permissionlessness targeted through decentralization milestones.", "Practitioner’s Note": "If Linea were removed, Ethereum would lose a ZK rollup tightly integrated with the ConsenSys stack, reducing zkEVM options aligned with Ethereum’s dominant developer tooling provider.", "Proof System Type": "SNARK-based (zk-SNARK family).", "Prover Architecture": "Currently permissioned / operator-led proving, with decentralization planned over time.", "Prover Bottlenecks": "- Compute-intensive proving\n- Specialized hardware and optimization requirements\n- Centralization risk until prover participation broadens", "Proving Cost Characteristics": "High fixed prover costs with improving marginal efficiency as transaction volume increases.", "Reason for Inclusion": "Implements production ZK-rollup infrastructure where Ethereum-equivalent execution semantics are enforced through validity proofs verified on Ethereum, backed by one of Ethereum’s core infrastructure providers.", "Reorg / Failure Handling Model": "- Post-L1 finalization: no L2 reorg risk beyond Ethereum\n- Pre-finalization: soft finality dependent on sequencer/prover availability", "Reusable by Other Rollups": "Limited, zkEVM technology could theoretically be reused, but Linea is not positioned as a rollup-as-a-service platform.", "Security Inheritance from Ethereum": "Full settlement security once validity proofs are verified and finalized on Ethereum.", "Sequencer Model": "Single sequencer in current operation; sequencer decentralization is a stated roadmap goal.", "Shared Prover / Sequencer Assumptions": "Currently centralized at the network level.", "Single Canonical Rollup": "Yes, Linea operates as a single canonical ZK rollup.", "State Transition Definition": "Defined by Ethereum’s EVM specification; protocol upgrades track Ethereum hard forks and EIPs.", "Throughput Constraints": "Bounded by prover throughput, Ethereum calldata constraints, and batch aggregation efficiency.", "Time to Cryptographic Finality": "Finality achieved when validity proofs are verified and state updates are finalized on Ethereum (typically minutes to hours, depending on batch cadence and L1 conditions).", "Trust Assumptions Beyond Ethereum": "- Correctness of zkEVM circuits and prover implementation\n- Trusted setup assumptions typical of SNARK systems\n- Sequencer and prover liveness prior to L1 finalization", "Upgrade Authority": "Protocol upgrades controlled via admin/governance mechanisms; practitioners should assume active upgrade authority exists.", "Validity Proof Model": "Aggregated batch validity proofs; recursion used to amortize on-chain verification costs.", "Verifier Location": "Ethereum L1 smart contracts verify proofs and finalize state updates.", "Withdrawal Latency": "Withdrawals available after L1 proof verification and finalization; faster than optimistic rollups and dependent on proving cadence.", "ZK Rollup": "Linea"}, "source_label": "ZK Rollups"}'::jsonb),
  ('developed-and-stewarded-by-the-taiko-core-team-with-governance-structures-evolving-toward-community-participation', 'Developed and stewarded by the Taiko core team, with governance structures evolving toward community participation.', 'rollup-scaling-frameworks', 'zk-rollups', 'https://taiko.xyz', ARRAY['Not a primary design goal.']::text[], ARRAY[]::text[], '{"description": "An Ethereum L2 ZK validity rollup designed as a “based rollup”, aiming for maximal Ethereum alignment by using Ethereum L1 for sequencing and prioritizing EVM equivalence.", "extras": {"Cost Sensitivity to Usage": "Sensitive to Ethereum L1 gas prices due to tight coupling with L1 ordering and data availability.", "Decentralization Roadmap Credibility": "High conceptual credibility due to architectural choices (based sequencing), with execution dependent on prover decentralization milestones.", "Dependency on External Bridges": "Relies on external bridges and messaging layers for cross-chain interoperability.", "Developer Adoption Signal": "Attracts developers prioritizing Ethereum alignment and censorship resistance over early liquidity or maximal throughput.", "Ecosystem Dependency Risk": "Dependency on Ethereum L1 performance and Taiko-specific proving infrastructure.", "Emergency Controls": "Emergency pause and intervention mechanisms are present.", "Enterprise / Institutional Orientation": "Appeals to teams valuing decentralization and Ethereum-native guarantees; less oriented toward enterprise tooling integrations than Linea or Polygon zkEVM.", "Ethereum Composability Model": "Asynchronous composability via Ethereum settlement and messaging.", "Ethereum Settlement Path": "L1-ordered transactions → L2 execution → proof generation → L1 verification contract → finalized state on Ethereum.", "Execution Environment": "EVM-equivalent, designed to match Ethereum L1 semantics closely.", "Is This a Network or a Framework": "Primarily a network, with architectural principles that could influence future rollup designs.", "Mainnet Maturity": "Progressing toward maturity; design emphasizes correctness and alignment rather than rapid iteration.", "Native Cross-Rollup Support": "No native cross-rollup interoperability at the protocol level.", "Opinionated vs Modular Design": "Highly opinionated, prioritizing Ethereum alignment and decentralization over modular flexibility.", "Permissioned vs Permissionless Deployment": "Proving initially permissioned; sequencing inherits Ethereum’s permissionless model.", "Practitioner’s Note": "If Taiko were removed, Ethereum would lose its most explicit attempt at a based ZK rollup architecture using L1-driven sequencing.", "Proof System Type": "SNARK-based (zk-SNARK family).", "Prover Architecture": "Initially permissioned proving, with a roadmap toward permissionless prover participation.", "Prover Bottlenecks": "- Compute-intensive proving\n- Hardware and optimization requirements\n- Centralization risk until prover participation is permissionless", "Proving Cost Characteristics": "High fixed prover costs; marginal costs improve with batching efficiency.", "Reason for Inclusion": "Implements a ZK rollup that intentionally minimizes L2-specific trust assumptions by leveraging Ethereum L1 for sequencing, representing a distinct architectural path within ZK rollups.", "Reorg / Failure Handling Model": "- Post-L1 finalization: no L2 reorg risk beyond Ethereum\n- Pre-finalization: limited reorg risk due to reliance on Ethereum ordering rather than an L2 sequencer", "Reusable by Other Rollups": "Not positioned as a general-purpose rollup SDK.", "Security Inheritance from Ethereum": "Full settlement security once proofs are verified and finalized on Ethereum.", "Sequencer Model": "Based sequencing, transaction ordering derives from Ethereum L1 rather than a dedicated L2 sequencer.", "Shared Prover / Sequencer Assumptions": "Sequencing is shared with Ethereum L1; prover assumptions currently centralized.", "Single Canonical Rollup": "Yes, Taiko operates as a single canonical ZK rollup.", "State Transition Definition": "Defined by Ethereum’s EVM specification; protocol intentionally tracks Ethereum behavior with minimal divergence.", "Throughput Constraints": "Constrained by prover throughput and Ethereum L1 ordering constraints, trading raw throughput for alignment and decentralization.", "Time to Cryptographic Finality": "Finality achieved when validity proofs are verified and state updates are finalized on Ethereum; timing depends on proving cadence and L1 block inclusion.", "Trust Assumptions Beyond Ethereum": "- Correctness of zk circuits and prover implementation\n- Trusted setup assumptions (common to SNARK systems)\n- Reduced sequencer trust due to L1-based sequencing model", "Upgrade Authority": "Protocol upgrades controlled via governance/admin mechanisms; practitioners should assume active upgrade authority exists.", "Validity Proof Model": "Batch validity proofs with aggregation; recursion used to reduce on-chain verification overhead.", "Verifier Location": "Ethereum L1 smart contracts verify proofs and finalize state commitments.", "Withdrawal Latency": "Withdrawals are available after L1 proof verification and finalization; latency depends on proving cadence rather than challenge windows.", "ZK Rollup": "Taiko"}, "source_label": "ZK Rollups"}'::jsonb),
  ('developed-and-stewarded-by-matter-labs-with-governance-mechanisms-evolving-alongside-ecosystem-growth', 'Developed and stewarded by Matter Labs, with governance mechanisms evolving alongside ecosystem growth.', 'rollup-scaling-frameworks', 'zk-rollups', 'https://zksync.io/zk-stack', ARRAY['Yes', 'explicitly designed for multi-chain and appchain deployments.']::text[], ARRAY[]::text[], '{"description": "A modular ZK rollup framework developed by Matter Labs that enables teams to deploy Ethereum-anchored ZK rollups and validiums using shared infrastructure, tooling, and standards.", "extras": {"Cost Sensitivity to Usage": "Improves with scale and shared proving; still sensitive to Ethereum L1 gas prices and proof complexity.", "Decentralization Roadmap Credibility": "Moderate–high: clear intent toward decentralized proving and sequencing, but current deployments remain operator-led.", "Dependency on External Bridges": "Required for interoperability outside the ZK Stack ecosystem.", "Developer Adoption Signal": "Growing adoption among teams launching zkSync-based rollups and appchains rather than single shared environments.", "Ecosystem Dependency Risk": "Strong dependency on Matter Labs, zkSync tooling, and ZK Stack evolution.", "Emergency Controls": "Emergency pause and intervention mechanisms exist at the framework and deployment level.", "Enterprise / Institutional Orientation": "High, ZK Stack is explicitly positioned for custom chains, enterprise deployments, and app-specific rollups.", "Ethereum Composability Model": "Asynchronous composability via Ethereum settlement.", "Ethereum Settlement Path": "L2 execution → batch commitment → proof generation → ZK Stack L1 verifier contracts → finalized state on Ethereum.", "Execution Environment": "Primarily EVM-compatible, aligned with zkSync execution semantics.", "Is This a Network or a Framework": "Framework (not a single rollup).", "Mainnet Maturity": "Framework is production-ready; maturity depends on the operational quality of individual deployments.", "Native Cross-Rollup Support": "Strongest within the ZK Stack ecosystem (shared standards and tooling).", "Opinionated vs Modular Design": "Relatively modular, but opinionated around zkSync execution semantics and SNARK-based proving.", "Permissioned vs Permissionless Deployment": "Deployment is permissioned by framework governance, with varying permission models at the chain level.", "Practitioner’s Note": "If ZK Stack were removed, multiple zkSync-based rollups and appchains would lose their execution framework, proving pipeline, and settlement standard.", "Proof System Type": "SNARK-based (zk-SNARK family).", "Prover Architecture": "Initially permissioned / operator-led proving, with a roadmap toward decentralized prover participation.", "Prover Bottlenecks": "- Compute-intensive proving\n- Specialized hardware requirements\n- Centralization risk until prover markets mature", "Proving Cost Characteristics": "High fixed prover costs with shared infrastructure efficiencies across multiple rollups.", "Reason for Inclusion": "Defines execution, proving, and settlement architecture for multiple ZK rollups, materially shaping how ZK-based scaling systems operate on Ethereum.", "Reorg / Failure Handling Model": "- Post-L1 finalization: no reorg risk beyond Ethereum\n- Pre-finalization: soft finality dependent on sequencer/prover liveness", "Reusable by Other Rollups": "Yes, core purpose is multi-rollup deployment.", "Security Inheritance from Ethereum": "Configurable:\n- Full Ethereum settlement security for rollups\n- Partial security for validium-style deployments (DA off-chain)", "Sequencer Model": "Typically single sequencer per chain by default; decentralization models are configurable and roadmap-driven.", "Shared Prover / Sequencer Assumptions": "Can be shared or isolated depending on configuration; shared infrastructure is a core efficiency thesis.", "Single Canonical Rollup": "No, ZK Stack is not itself a rollup.", "State Transition Definition": "Defined by ZK Stack protocol specifications; rollup deployers inherit standardized state transition logic with limited customization.", "Throughput Constraints": "Bounded by prover capacity, batch aggregation efficiency, and Ethereum data posting constraints.", "Time to Cryptographic Finality": "Finality achieved once validity proofs are verified and state updates are finalized on Ethereum (dependent on batch cadence and proving throughput).", "Trust Assumptions Beyond Ethereum": "- Correctness of zk circuits and prover implementation\n- Trusted setup assumptions typical of SNARK systems\n- Operator assumptions for sequencing and proving (config-dependent)", "Upgrade Authority": "Framework-level upgrades controlled by governance/admin processes; changes propagate to dependent rollups.", "Validity Proof Model": "Supports aggregated and recursive validity proofs to amortize verification costs across batches and chains.", "Verifier Location": "Ethereum L1 smart contracts verify proofs and finalize state commitments.", "Withdrawal Latency": "Dependent on proof finalization and bridge configuration; generally faster than optimistic rollups and variable across deployments.", "ZK Rollup": "ZK Stack"}, "source_label": "ZK Rollups"}'::jsonb),
  ('owned-and-operated-by-starkware-in-coordination-with-deploying-applications', 'Owned and operated by StarkWare in coordination with deploying applications.', 'rollup-scaling-frameworks', 'zk-rollups', 'https://starkware.co/starkex', ARRAY['Yes', 'but in a custom', 'permissioned manner.']::text[], ARRAY[]::text[], '{"description": "A ZK-based scaling engine developed by StarkWare that enables applications to operate as ZK rollups or validiums, settling state to Ethereum using STARK validity proofs.", "extras": {"Cost Sensitivity to Usage": "Favorable economics at high scale; less suitable for small or low-volume applications.", "Decentralization Roadmap Credibility": "Low, StarkEx is not designed to become a permissionless, decentralized framework; it prioritizes performance and reliability over decentralization.", "Dependency on External Bridges": "Required for interoperability beyond Ethereum L1.", "Developer Adoption Signal": "Adopted by large, sophisticated teams requiring custom ZK infrastructure rather than shared execution environments.", "Ecosystem Dependency Risk": "High dependency on StarkWare as a single provider and operator.", "Emergency Controls": "Strong operator-level emergency controls and pause mechanisms.", "Enterprise / Institutional Orientation": "Very high, StarkEx is effectively enterprise-grade ZK infrastructure.", "Ethereum Composability Model": "Asynchronous composability via Ethereum settlement.", "Ethereum Settlement Path": "Application execution → batch commitment → STARK proof generation → L1 verification contracts → finalized state on Ethereum.", "Execution Environment": "Custom execution environment, application-specific; not EVM-equivalent.", "Is This a Network or a Framework": "Framework / execution engine, not a public rollup network.", "Mainnet Maturity": "Highly mature in production; used for years in real-world, high-throughput systems.", "Native Cross-Rollup Support": "None at the protocol level.", "Opinionated vs Modular Design": "Highly opinionated, optimized for performance, scale, and custom logic.", "Permissioned vs Permissionless Deployment": "Strictly permissioned, requiring StarkWare involvement.", "Practitioner’s Note": "If StarkEx were removed, several major Ethereum applications would lose their ZK execution and validity-proof settlement engine, breaking live production systems.", "Proof System Type": "STARK-based (transparent proofs, no trusted setup).", "Prover Architecture": "Centralized / permissioned proving, operated by StarkWare infrastructure.", "Prover Bottlenecks": "- Heavy compute requirements\n- Specialized hardware\n- Full centralization at the prover layer", "Proving Cost Characteristics": "High fixed proving costs, amortized efficiently at scale for large, high-throughput applications.", "Reason for Inclusion": "Defines production ZK execution, proving, and settlement logic used by multiple large-scale Ethereum applications, materially influencing how ZK-based scaling has operated in production.", "Reorg / Failure Handling Model": "- Post-L1 verification: no reorg risk beyond Ethereum\n- Pre-finalization: operational risk tied to operator availability and DA assumptions", "Reusable by Other Rollups": "Yes, but only via bespoke, application-specific deployments.", "Security Inheritance from Ethereum": "Configurable:\n- Full Ethereum settlement security in ZK Rollup mode\n- Partial security in Validium mode (off-chain data availability)", "Sequencer Model": "Typically single operator sequencing, application-specific.", "Shared Prover / Sequencer Assumptions": "Shared at the application deployment level; not a public shared market.", "Single Canonical Rollup": "No, each StarkEx deployment is application-specific.", "State Transition Definition": "Defined per application in collaboration with StarkWare; highly custom and rigid relative to general-purpose rollups.", "Throughput Constraints": "Optimized for high-volume, application-specific workloads; constrained by prover throughput and DA model.", "Time to Cryptographic Finality": "Finality achieved when STARK proofs are verified and state updates are finalized on Ethereum; cadence determined by application batching.", "Trust Assumptions Beyond Ethereum": "- Correctness of STARK prover and circuits\n- Data availability assumptions (critical in Validium deployments)\n- Operator trust for sequencing and data publication", "Upgrade Authority": "Upgrades coordinated between StarkWare and the application operator; highly centralized.", "Validity Proof Model": "Aggregated STARK proofs over batches of application-specific state transitions; recursion used for scalability.", "Verifier Location": "Ethereum L1 smart contracts verify STARK proofs and accept finalized state commitments.", "Withdrawal Latency": "- ZK Rollup mode: withdrawals after L1 proof finalization\n- Validium mode: withdrawals depend on data availability guarantees and operator behavior", "ZK Rollup": "StarkEx (borderline but architecturally critical)"}, "source_label": "ZK Rollups"}'::jsonb),
  ('arbitrum-orbit', 'Arbitrum Orbit', 'rollup-scaling-frameworks', 'l3-appchain-frameworks', 'https://arbitrum.io/orbit', ARRAY['Arbitrum Nitro (Optimistic Rollup execution).']::text[], ARRAY['Appchain', 'L3 framework (supports L2→L3 patterns).']::text[], '{"description": "A framework enabling teams to launch application-specific Arbitrum chains (Orbit chains) that settle to Ethereum via Arbitrum (L2 or L3), inheriting Arbitrum’s optimistic execution and settlement model.", "extras": {"Base Layer Dependency": "Arbitrum One / Arbitrum Nova (configurable).", "Bespoke Engineering Required": "Limited — application logic and configuration, not protocol design.", "Composability with Base Rollup": "Asynchronous composability with Arbitrum L2.", "Configurable Parameters": "Gas pricing, block times, fee models, sequencer operation, upgrade cadence.", "Cross-Rollup Messaging Assumptions": "Relies on bridges/messaging layers external to Orbit.", "Dependency Concentration Risk": "High dependency on Arbitrum’s roadmap and governance outcomes.", "Does This Enable L3s": "Yes — Orbit commonly used for L3 appchains settling to Arbitrum.", "Ecosystem Alignment": "Strong alignment with Arbitrum ecosystem and tooling.", "Emergency Controls": "Deployer-defined emergency controls; upstream Arbitrum safeguards apply.", "Execution Environment Options": "EVM-equivalent (inherits Arbitrum EVM semantics).", "External Bridge Dependency": "Yes — required for broader Ethereum and cross-rollup interoperability.", "Failure Propagation Model": "L3 issues can cascade to L2 (Arbitrum) before reaching L1.", "Fault / Validity Proof Inheritance": "Inherits Arbitrum fraud-proof system and challenge assumptions.", "Fixed vs Variable Costs": "Fixed costs for sequencer/infrastructure; variable costs tied to usage and upstream fees.", "Framework Ownership": "Developed by Offchain Labs; ecosystem governed via Arbitrum DAO.", "Infrastructure Responsibility Split": "Deployer manages chain ops; Arbitrum manages upstream protocol.", "Isolation vs Shared Security": "Execution isolated per chain; settlement and security shared upstream.", "Latency Trade-offs": "Lower fees and higher throughput at the cost of additional settlement hops.", "Level of Protocol Abstraction": "High — standardized deployment, configuration, and contracts.", "Native Interoperability Support": "Best within Arbitrum ecosystem; no native cross-L2 standard.", "Number of Chains Deployed": "Multiple Orbit chains live or announced across gaming, DeFi, and infra.", "Operational Complexity": "Medium — simpler than building a rollup from scratch; more complex than deploying on an L2.", "Path to Sovereignty": "Moderate — appchains retain operational control but depend on Arbitrum protocol evolution.", "Practitioner Validation Check": "If Orbit were removed, teams would need to rebuild Arbitrum-compatible rollup logic to launch Arbitrum-anchored appchains.", "Practitioner''s Note": "Orbit should be evaluated as a scaling deployment abstraction on top of Arbitrum Nitro, not as a standalone rollup. Design choices largely inherit Arbitrum’s optimistic assumptions.", "Reason of inclusion": "Provides standardized rollup/appchain deployment templates (execution, settlement, security) that allow teams to launch Ethereum-anchored chains without bespoke protocol engineering.", "Security Inheritance": "Indirect Ethereum security; direct inheritance from Arbitrum’s optimistic model.", "Sequencer Model Options": "Single sequencer by default; customization possible per deployment.", "Settlement Layer": "Ethereum L1 via Arbitrum (Orbit chains typically settle to Arbitrum, which settles to Ethereum).", "Types of Users": "Application teams seeking custom execution environments.", "Upgrade Model": "Per-chain upgrades by deployer, constrained by Nitro compatibility.", "Vendor Lock-in Risk": "Moderate — tight coupling to Arbitrum Nitro and ecosystem.", "Who Controls Upgrades": "Chain deployer controls appchain upgrades; core Nitro changes governed upstream."}, "source_label": "L3 & Appchain Frameworks"}'::jsonb),
  ('op-stack-already-used-but-also-belongs-here-contextually', 'OP Stack (already used, but also belongs here contextually)', 'rollup-scaling-frameworks', 'l3-appchain-frameworks', 'https://optimism.io/op-stack', ARRAY['Native Optimistic Rollup design maintained by the Optimism ecosystem.']::text[], ARRAY['Rollup', 'Appchain', 'L3 framework.']::text[], '{"description": "A modular, open-source Optimistic Rollup framework that enables teams to deploy Ethereum-anchored L2s and L3s with standardized execution, settlement, and governance components.", "extras": {"Base Layer Dependency": "Ethereum L1 or OP Stack L2s (configurable).", "Bespoke Engineering Required": "Limited — teams configure parameters and infrastructure rather than designing protocol mechanics.", "Composability with Base Rollup": "Asynchronous composability with Ethereum and Superchain peers.", "Configurable Parameters": "Gas pricing, block time, fee routing, sequencer setup, upgrade cadence.", "Cross-Rollup Messaging Assumptions": "Relies on standardized OP Stack messaging patterns.", "Dependency Concentration Risk": "Shared framework risk across all OP Stack chains.", "Does This Enable L3s": "Yes — OP Stack supports L3-style deployments (e.g., appchains settling to OP-based L2s).", "Ecosystem Alignment": "Strong alignment within the OP Superchain.", "Emergency Controls": "Emergency pause and intervention mechanisms exist at both framework and chain levels.", "Execution Environment Options": "EVM-equivalent (designed to closely mirror Ethereum L1 semantics).", "External Bridge Dependency": "Arbitrum Orbit\nOP Stack (already used, but also belongs here contextually)\nZK Stack\nPolygon CDK\nAvalanche HyperSDK (Ethereum-anchored variants only)\nCaldera\nConduit", "Failure Propagation Model": "L3 → L2 → L1, depending on deployment topology.", "Fault / Validity Proof Inheritance": "Inherits OP Stack fraud-proof system and challenge window assumptions.", "Fixed vs Variable Costs": "Fixed costs for sequencing and infra; variable costs driven by L1 data posting and usage.", "Framework Ownership": "Maintained by the Optimism ecosystem; governed by the Optimism Collective.", "Infrastructure Responsibility Split": "Chain operators manage execution infra; Optimism maintains core framework.", "Isolation vs Shared Security": "Execution isolated per chain; security and settlement assumptions shared across OP Stack chains.", "Latency Trade-offs": "Improved throughput and lower fees with additional settlement hops.", "Level of Protocol Abstraction": "High — standardized contracts, execution clients, and configuration templates.", "Native Interoperability Support": "Designed for Superchain-native interoperability (shared standards and messaging assumptions).", "Number of Chains Deployed": "Multiple production chains (e.g., Base, Optimism, others in the Superchain).", "Operational Complexity": "Medium — simpler than bespoke rollup design; requires infra management beyond standard L2 deployment.", "Path to Sovereignty": "Moderate — chains retain operational control but share core protocol evolution with the Superchain.", "Practitioner Validation Check": "If OP Stack were removed, multiple Ethereum-anchored rollups and appchains would lose their execution framework, fraud-proof logic, and settlement standard.", "Practitioner''s Note": "OP Stack should be evaluated as a rollup operating system, not a single chain. Its design choices propagate across all OP Stack–based chains (the Superchain).", "Reason of inclusion": "Defines a reusable rollup and appchain deployment standard that allows teams to launch Ethereum-settled chains without rebuilding optimistic rollup protocol logic.", "Security Inheritance": "Full Ethereum settlement security via optimistic assumptions.", "Sequencer Model Options": "Single sequencer by default; roadmap includes shared and decentralized sequencing.", "Settlement Layer": "Ethereum L1 (direct settlement).", "Types of Users": "Application teams, enterprises, and ecosystems seeking standardized Ethereum rollups.", "Upgrade Model": "Framework upgrades coordinated at the Superchain level; per-chain upgrades possible within constraints.", "Vendor Lock-in Risk": "Moderate — tight coupling to OP Stack standards and Superchain governance.", "Who Controls Upgrades": "Framework upgrades coordinated by Optimism governance; chain operators control local configuration."}, "source_label": "L3 & Appchain Frameworks"}'::jsonb),
  ('zk-stack', 'ZK Stack', 'rollup-scaling-frameworks', 'l3-appchain-frameworks', 'https://zksync.io/zk-stack', ARRAY['zkSync ZK rollup architecture (SNARK-based validity proofs).']::text[], ARRAY['ZK rollup', 'appchain', 'L3 framework.']::text[], '{"description": "A modular ZK rollup and appchain framework that enables teams to deploy Ethereum-anchored ZK rollups, L3s, and validiums using shared proving, execution, and settlement standards.", "extras": {"Base Layer Dependency": "Ethereum L1; optional dependency on zkSync Era as an ecosystem hub.", "Bespoke Engineering Required": "Limited — configuration and infra integration, not protocol design.", "Composability with Base Rollup": "Asynchronous composability with Ethereum and zkSync-based chains.", "Configurable Parameters": "DA mode (rollup vs validium), gas model, block times, fee routing, sequencer configuration.", "Cross-Rollup Messaging Assumptions": "Relies on standardized ZK Stack messaging patterns.", "Dependency Concentration Risk": "High dependency on ZK Stack governance and shared proving infrastructure.", "Does This Enable L3s": "Yes — explicitly supports L3-style zkChains settling to Ethereum (directly or via L2).", "Ecosystem Alignment": "Strong alignment within the zkSync / ZK Stack ecosystem.", "Emergency Controls": "Emergency pause and intervention mechanisms exist at framework and chain levels.", "Execution Environment Options": "Primarily EVM-compatible (zkSync execution semantics).", "External Bridge Dependency": "Required for interoperability outside the ZK Stack ecosystem.", "Failure Propagation Model": "L3 → L2 (if used) → L1, depending on deployment topology.", "Fault / Validity Proof Inheritance": "Inherits ZK validity-proof system defined by ZK Stack.", "Fixed vs Variable Costs": "High fixed prover costs; variable costs scale with usage and L1 data posting.", "Framework Ownership": "Developed and stewarded by Matter Labs, with ecosystem governance evolving over time.", "Infrastructure Responsibility Split": "Chain deployers manage infra; ZK Stack provides protocol and tooling.", "Isolation vs Shared Security": "Execution isolated per chain; proving and settlement standards shared.", "Latency Trade-offs": "Lower fees and faster UX at the cost of additional settlement layers.", "Level of Protocol Abstraction": "High — standardized contracts, provers, and deployment workflows.", "Native Interoperability Support": "Strongest within the ZK Stack ecosystem (shared standards and tooling).", "Number of Chains Deployed": "Growing number of zkChains and appchains built on ZK Stack.", "Operational Complexity": "Medium–high — ZK proving infrastructure adds complexity relative to optimistic stacks.", "Path to Sovereignty": "Moderate — chains gain operational control but remain coupled to ZK Stack evolution.", "Practitioner Validation Check": "If ZK Stack were removed, teams would need to rebuild ZK execution, proving pipelines, and Ethereum settlement logic to launch zkSync-style chains.", "Practitioner''s Note": "ZK Stack should be evaluated as a ZK-native rollup operating system: it emphasizes cryptographic finality, configurable DA models, and a multi-chain ecosystem rather than a single shared execution environment.", "Reason of inclusion": "Defines standardized deployment templates, execution semantics, and settlement models that allow teams to launch ZK-based chains without bespoke protocol engineering.", "Security Inheritance": "Configurable:\n- Full Ethereum security for rollup deployments\n- Partial security for validium deployments (off-chain DA)", "Sequencer Model Options": "Single sequencer per chain by default; decentralization models are roadmap-driven and configurable.", "Settlement Layer": "Ethereum L1 (direct settlement).", "Types of Users": "Application teams, enterprises, and ecosystems requiring custom ZK execution.", "Upgrade Model": "Framework-level upgrades coordinated by ZK Stack governance; per-chain upgrades possible within constraints.", "Vendor Lock-in Risk": "Moderate–high — tight coupling to ZK Stack tooling and Matter Labs roadmap.", "Who Controls Upgrades": "Framework upgrades governed centrally; chain deployers control local configuration."}, "source_label": "L3 & Appchain Frameworks"}'::jsonb)
) AS v(slug, name, sector_slug, subsector_slug, website, chains, tags, meta)
JOIN public.sectors sec ON sec.slug = v.sector_slug
JOIN public.subsectors s ON s.sector_id = sec.id AND s.slug = v.subsector_slug
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  subsector_id = EXCLUDED.subsector_id,
  website = EXCLUDED.website,
  chains = EXCLUDED.chains,
  tags = EXCLUDED.tags,
  meta = EXCLUDED.meta,
  updated_at = NOW();
